import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api, formatApiError } from "../lib/api";
import { useAuth } from "../lib/auth";
import { toast } from "sonner";
import LoadingSpinner from "../components/LoadingSpinner";
import ConfirmDialog from "../components/ConfirmDialog";
import TextEditDialog from "../components/TextEditDialog";

export default function ContributorsIndex() {
  const [c, setC] = useState([]);
  const { user } = useAuth();
  const [pageLoading, setPageLoading] = useState(true);
  const [actionLoadingId, setActionLoadingId] = useState(null);
  const [selectedContributor, setSelectedContributor] = useState(null);
  const [deleteContributor, setDeleteContributor] = useState(null);

  useEffect(() => {
    api.get("/contributors")
      .then((r) => setC(r.data))
      .catch(() => {})
      .finally(() => setPageLoading(false));
  }, []);

  const removeContributor = async (id) => {
    setActionLoadingId(id);
    try {
      await api.delete(`/contributors/${id}`);
      setC((s) => s.filter((x) => x.id !== id));
      toast.success("Contributor deleted");
    } catch (error) {
      toast.error(formatApiError(error.response?.data?.detail));
    } finally {
      setActionLoadingId(null);
      setDeleteContributor(null);
    }
  };

  return (
    <div className="max-w-[1480px] mx-auto px-6 py-12">
      <div className="meta-ink mb-3">section 06 · the keepers</div>
      <h1 className="font-display font-black text-5xl md:text-7xl tracking-tighter">curators.</h1>
      <p className="font-editorial italic text-xl mt-3 max-w-2xl">people who know things. their taste is the algorithm. follow generously.</p>
      {pageLoading ? (
        <div className="py-20 text-center meta-ink">
          <LoadingSpinner size={24} />
          <div className="mt-4">loading curators…</div>
        </div>
      ) : (
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-5 mt-10">
          {c.map((x) => {
          const scenes = Array.isArray(x.scenes) ? x.scenes : [];
          const displayName = x.name || x.handle || "curator";

          return (
            <Link key={x.handle || x.id} to={`/c/${x.handle || x.id}`} className="brutal-card p-6" data-testid={`contrib-${x.handle || x.id}`}>
              <div className="flex items-center gap-3">
                <div className="w-14 h-14 border-2 border-[var(--ink)] bg-[var(--hyperpop)] text-white flex items-center justify-center font-display font-black text-2xl">{displayName[0]?.toUpperCase()}</div>
                <div>
                  <div className="font-display font-bold text-lg">@{x.handle}</div>
                  <div className="meta-ink">depth {x.depth_score} · {scenes.join(", ")}</div>
                </div>
              </div>
              <p className="font-editorial italic mt-3 text-lg">{x.bio}</p>
              <div className="flex gap-2 mt-4">
                <span className="tag-chip">{x.lore_count} lore</span>
                <span className="tag-chip">{x.theory_count} theories</span>
                {user?.role === "admin" && (
                  <div className="ml-auto flex gap-2">
                    <button
                      className="brutal-btn"
                      onClick={(e) => {
                        e.preventDefault();
                        setSelectedContributor(x);
                      }}
                      disabled={actionLoadingId !== null && actionLoadingId !== x.id}
                    >
                      {actionLoadingId === x.id ? (
                        <>
                          <LoadingSpinner size={16} /> <span className="ml-2">Saving</span>
                        </>
                      ) : (
                        "Edit"
                      )}
                    </button>
                    <button
                      className="brutal-btn"
                      onClick={(e) => {
                        e.preventDefault();
                        setDeleteContributor(x);
                      }}
                      disabled={actionLoadingId !== null && actionLoadingId !== x.id}
                    >
                      {actionLoadingId === x.id ? (
                        <>
                          <LoadingSpinner size={16} /> <span className="ml-2">Deleting</span>
                        </>
                      ) : (
                        "Delete"
                      )}
                    </button>
                  </div>
                )}
              </div>
            </Link>
          );
        })}
          {c.length === 0 && (
            <p className="meta-ink">no curators found. check back later.</p>
          )}
        </div>
      )}

      <TextEditDialog
        open={Boolean(selectedContributor)}
        title="Edit contributor"
        label="Name"
        value={selectedContributor?.name}
        placeholder="Contributor name"
        loading={actionLoadingId === selectedContributor?.id}
        onCancel={() => setSelectedContributor(null)}
        onSave={async (name) => {
          if (!selectedContributor) return;
          setActionLoadingId(selectedContributor.id);
          try {
            await api.put(`/contributors/${selectedContributor.id}`, { name });
            setC((current) => current.map((item) => (item.id === selectedContributor.id ? { ...item, name } : item)));
            toast.success("Contributor updated");
            setSelectedContributor(null);
          } catch (error) {
            toast.error(formatApiError(error.response?.data?.detail));
          } finally {
            setActionLoadingId(null);
          }
        }}
      />

      <ConfirmDialog
        open={Boolean(deleteContributor)}
        title="Delete contributor"
        description={deleteContributor ? `Delete ${deleteContributor.name}?` : ""}
        confirmLabel="Delete"
        cancelLabel="Cancel"
        danger
        loading={actionLoadingId === deleteContributor?.id}
        onCancel={() => setDeleteContributor(null)}
        onConfirm={() => removeContributor(deleteContributor.id)}
      />
    </div>
  );
}
